  const views={
    templates:'<section class="panel"><p class="eyebrow">BIBLIOTECA DA EQUIPE</p><h2>Templates Canva</h2><p class="micro">A biblioteca é compartilhada por toda a equipe: os mesmos templates aparecem em todos os perfis.</p><form id="templateForm" class="grid2"><label class="field">Nome<input name="name" required></label><label class="field">Link do Canva<input name="url" type="url" required placeholder="https://www.canva.com/design/..."></label><label class="field">Formato<select name="format"><option>Stories</option><option>Post estático</option><option>Capa de Reels</option><option>Carrossel</option><option>Live</option></select></label><label class="field">Observação<input name="note"></label><button class="button primary">Salvar template</button></form><div class="template-library-head"><strong id="templateCount">0 templates</strong><div id="templateFilters" class="template-filters" role="group" aria-label="Filtrar templates"><button type="button" class="active" data-template-filter="Todos">Todos</button><button type="button" data-template-filter="Stories">Stories</button><button type="button" data-template-filter="Post estático">Posts estáticos</button><button type="button" data-template-filter="Capa de Reels">Capas de Reels</button><button type="button" data-template-filter="Carrossel">Carrossel</button><button type="button" data-template-filter="Live">Lives</button></div></div><div id="templateList" class="template-gallery"></div></section>',
    brain:'<section class="panel brain-panel"><p class="eyebrow">MEMORIA VIVA DO PERFIL</p><h2>Segundo cerebro</h2><p class="micro">O perfil selecionado e consultado pela Devil em cada criacao. Registre rotina, bastidores e historias em cartoes separados; corrija o resumo do que ela sabe sempre que precisar.</p><label class="field">Perfil<select id="brainProfile"></select></label><nav class="brain-tabs"><button type="button" data-brain-tab="knowledge">O que a Devil sabe</button><button type="button" data-brain-tab="routine">Rotina</button><button type="button" data-brain-tab="backstage">Bastidores</button><button type="button" data-brain-tab="stories">Historias</button></nav><section class="brain-pane" data-brain-pane="knowledge"><p class="micro">Resumo atual montado com o perfil, a oferta, as condicoes e os registros deste Segundo Cerebro. Edite e salve para corrigir o que a Devil sabe.</p><label class="field">O que a Devil sabe sobre este perfil<textarea id="brainKnowledge" rows="12"></textarea></label><div class="action-row"><button class="button primary" id="saveBrain">Salvar conhecimento</button><button class="button" id="refreshBrainKnowledge">Atualizar a partir do perfil</button><button class="button" id="recordBrainKnowledge">Gravar complemento</button><button class="button" id="stopBrainKnowledge" hidden>Concluir audio</button><label class="button">Anexar audio ou material<input id="brainKnowledgeFiles" type="file" accept=".pdf,.txt,.md,.docx,audio/*" multiple hidden></label></div><p class="micro" id="brainKnowledgeStatus" role="status"></p></section><section class="brain-pane" data-brain-pane="routine" hidden><h3>Rotina</h3><p class="micro">Registre cenas reais do dia a dia. Cada registro fica em um cartao com tema proprio.</p><label class="field">Tema da rotina<input id="brainEntryTitle" data-brain-title="routine" placeholder="Ex.: Manha de atendimento e treino"></label><label class="field">O que aconteceu?<textarea id="brainEntryText" data-brain-text="routine" rows="5" placeholder="Conte o que aconteceu, o que voce pensou e os detalhes que tornam a cena sua."></textarea></label><div class="action-row"><button class="button primary" data-save-brain-entry="routine">Salvar rotina</button><button class="button" id="recordBrainEntry">Gravar audio</button><button class="button" id="stopBrainEntry" hidden>Concluir audio</button><label class="button">Anexar audio ou arquivo<input id="brainEntryFiles" data-brain-files="routine" type="file" accept=".pdf,.txt,.md,.docx,audio/*" multiple hidden></label></div><p class="micro" id="brainStatus" role="status"></p><div class="brain-entry-grid" id="brainRoutineItems"></div></section><section class="brain-pane" data-brain-pane="backstage" hidden><h3>Bastidores</h3><p class="micro">Grave reuniões, atendimentos ou conversas por até 1 ou 2 horas. A transcrição é atualizada em trechos durante a gravação e, ao encerrar, a IA gera um resumo para a memória deste perfil.</p><label class="field">Tema da conversa<input id="brainEntryTitleBackstage" data-brain-title="backstage" placeholder="Ex.: Atendimento sobre dificuldades com alimentação"></label><div class="brain-session-controls"><label class="field">Limite da gravação<select id="brainSessionLimit"><option value="60">1 hora</option><option value="120" selected>2 horas</option></select></label><div class="action-row"><button class="button primary" id="recordBrainBackstage" type="button">🎙 Gravar conversa</button><button class="button" id="stopBrainBackstage" type="button" hidden>Parar e gerar resumo</button><span id="brainBackstageTimer" class="brain-session-timer">00:00:00</span></div><p class="micro brain-privacy-note">Grave somente com consentimento de quem participa. Evite nomes, contatos e outros dados que identifiquem pacientes. O DEVIL não guarda o arquivo de áudio; ele é enviado ao serviço de transcrição. A transcrição e o resumo ficam na memória privada deste perfil.</p></div><label class="field">Transcrição ao vivo<textarea id="brainEntryTextBackstage" data-brain-text="backstage" rows="8" placeholder="A transcrição aparecerá aqui enquanto a conversa é gravada. Você também pode escrever ou corrigir o texto."></textarea></label><div class="action-row"><button class="button" data-save-brain-entry="backstage">Salvar bastidor manualmente</button><label class="button">Anexar documento ou material<input id="brainEntryFilesBackstage" data-brain-files="backstage" type="file" accept=".pdf,.txt,.md,.docx" multiple hidden></label></div><p class="micro" id="brainStatusBackstage" role="status"></p><div class="brain-entry-grid" id="brainBackstageItems"></div></section><section class="brain-pane" data-brain-pane="stories" hidden><h3>Historias</h3><p class="micro">Cada historia e salva separadamente com tema e relato. Use texto ou grave seu audio; a transcricao vira um novo cartao.</p><label class="field">Tema da historia<input id="brainEntryTitleStories" data-brain-title="stories" placeholder="Ex.: A conversa que mudou minha forma de atender"></label><label class="field">A historia<textarea id="brainEntryTextStories" data-brain-text="stories" rows="6" placeholder="Conte a cena, quem estava envolvido, o que aconteceu e o que mudou depois."></textarea></label><div class="action-row"><button class="button primary" data-save-brain-entry="stories">Salvar historia</button><button class="button" id="recordBrainStories">Gravar audio</button><button class="button" id="stopBrainStories" hidden>Concluir audio</button><label class="button">Anexar audio ou arquivo<input id="brainEntryFilesStories" data-brain-files="stories" type="file" accept=".pdf,.txt,.md,.docx,audio/*" multiple hidden></label></div><p class="micro" id="brainStatusStories" role="status"></p><div class="brain-entry-grid" id="brainStoriesItems"></div></section></section>',
    sos:'<section class="panel"><p class="eyebrow">RESPOSTA RÁPIDA</p><h2>SOS de conteúdo</h2><label class="field">Perfil<select id="sosProfile"></select></label><label class="field">Preciso de ajuda para<select id="sosType"><option>Ter uma ideia de conteúdo</option><option>Adaptar uma trend</option><option>Adaptar ou melhorar uma copy</option><option>Melhorar minha bio</option><option>Responder alguém da audiência</option><option>Quebrar uma objeção</option><option>Outro pedido rápido</option></select></label><aside class="sos-download-card"><div><strong>Quer adaptar um vídeo do Instagram?</strong><p class="micro">O link sozinho não permite que a Devil assista ao conteúdo. Baixe o vídeo e anexe aqui.</p></div><a class="button tiny" href="https://sssinstagram.com/pt#google_vignette" target="_blank" rel="noopener noreferrer">Abrir baixador do Instagram ↗</a></aside><label class="field">Contexto e descrição<textarea id="sosText" rows="6" placeholder="Conte o que quer adaptar. Você também pode colar um print diretamente neste campo."></textarea></label><p class="micro">Cole imagens com Ctrl+V ou anexe imagens e vídeos. Vídeos maiores que 10 MB serão analisados por três quadros; inclua a transcrição para adaptar as falas com precisão.</p><div id="sosReferencePreview" class="sos-reference-grid"></div><div class="action-row"><button class="button" id="recordSos">Gravar áudio</button><button class="button" id="stopSos" hidden>Concluir</button><label class="button">Anexar arquivos<input id="sosFiles" type="file" accept=".mp4,.webm,.mov,.m4v,.pdf,.txt,.md,.docx,audio/*,image/*,video/*" multiple hidden></label></div><p id="sosStatus" class="micro" role="status"></p><button class="button primary" id="runSos">Criar resposta</button><div id="sosOutput" class="design-audit" hidden></div><div id="sosHistory" class="cards"></div></section>',
    analysis:'<section class="panel"><p class="eyebrow">DIAGNÓSTICO E PRÓXIMA AÇÃO</p><h2>Análises</h2><label class="field">Perfil<select id="analysisProfile"></select></label><label class="field">O que analisar<select id="analysisType"><option>Perfil do Instagram</option><option>Bio</option><option>Vídeo ou Reels</option><option>Design de post</option><option>Criativo</option><option>Legenda</option><option>Resposta para a audiência</option><option>Outro material</option></select></label><label class="field">O que você quer entender ou melhorar?<textarea id="analysisText" rows="5"></textarea></label><div class="action-row"><button class="button" id="recordAnalysis">Gravar áudio</button><button class="button" id="stopAnalysis" hidden>Concluir</button><label class="button">Anexar imagem, vídeo, PDF ou áudio<input id="analysisFiles" type="file" accept="image/*,video/*,.pdf,.txt,.md,audio/*" multiple hidden></label></div><p id="analysisStatus" class="micro"></p><button class="button primary" id="runAnalysis">Analisar material</button><div id="analysisOutput" class="design-audit" hidden></div><div id="analysisHistory" class="cards"></div></section>',
    history:'<section class="panel"><p class="eyebrow">CRIAÇÕES RECENTES</p><h2>Histórico</h2><p class="micro">Conteúdos, pedidos e análises dos últimos 30 dias. Abra ou use como ponto de partida.</p><div class="grid2"><label class="field">Buscar<input id="historySearch" type="search" placeholder="Título, tema ou texto"></label><label class="field">Tipo<select id="historyFilter"><option value="all">Tudo</option><option value="content">Conteúdos</option><option value="sos">SOS</option><option value="analysis">Análises</option></select></label></div><div id="historyList" class="cards"></div></section>',
    ideas:'<section class="panel idea-workspace"><div class="idea-page-head"><div><p class="eyebrow">IDEIAS ORGANIZADAS PARA SAIR DO PAPEL</p><h2>Banco de ideias</h2><p class="micro">Conecte a lista do ClickUp deste perfil. As ideias aparecem em lista com status e detalhes, junto das refer&ecirc;ncias salvas no Instagram.</p></div><span class="idea-count-badge" id="ideaCountBadge">0 ideias</span></div><div class="grid2 idea-controls"><label class="field">Pasta / perfil<select id="ideasProfile"></select></label><label class="field">Buscar ideia<input id="ideaSearch" type="search" placeholder="T&iacute;tulo, cole&ccedil;&atilde;o ou descri&ccedil;&atilde;o"></label></div><section class="idea-source-card"><div class="idea-source-copy"><span class="idea-source-icon">&#8599;</span><div><b>Lista de ideias do ClickUp</b><small>O link fica salvo neste perfil e pode ser atualizado a qualquer momento.</small></div></div><label class="field idea-url-field">Link da lista<input id="clickupIdeasUrl" type="url" placeholder="https://app.clickup.com/.../li/..."></label><div class="idea-source-actions"><button class="button" id="saveClickUpIdeasUrl" type="button">Salvar link</button><button class="button primary" id="syncClickUpIdeas" type="button">Sincronizar ideias</button></div><p class="micro idea-source-status" id="clickUpIdeasStatus" role="status"></p></section><details class="idea-instagram-tools"><summary>Importar refer&ecirc;ncias salvas do Instagram</summary><div class="idea-instagram-actions"><label class="field idea-import">Arquivo exportado do Instagram<input id="instagramExport" type="file" accept=".zip,.json,.html,.htm,application/zip,application/json,text/html"></label><button class="button" id="importInstagramIdeas">Importar arquivo</button><button class="button" id="clearInstagramIdeas">Remover importa&ccedil;&atilde;o do Instagram</button></div></details><div class="idea-list-toolbar"><span>IDEIAS E STATUS</span><div id="ideaStatusFilters" class="idea-status-filters"></div></div><p class="micro" id="ideasStatus" role="status"></p><div class="idea-layout"><div class="idea-list-wrap" id="ideasList" role="list"></div></div><dialog id="ideaTaskDialog" class="idea-task-dialog" aria-labelledby="ideaTaskDialogTitle"><div class="idea-task-shell"><header class="idea-task-head"><button class="button tiny" id="closeIdeaTask" type="button">&#8592; Voltar para a lista</button><span class="idea-task-context" id="ideaTaskContext">IDEIA</span><button class="idea-task-close" id="closeIdeaTaskX" type="button" aria-label="Fechar tarefa">&times;</button></header><div class="idea-task-content"><main id="ideaDetail" class="idea-detail cu-detail"><p class="no-data">Selecione uma ideia para abrir.</p></main><aside class="idea-task-notes"><p class="eyebrow">ACOMPANHAMENTO</p><h3 id="ideaTaskDialogTitle">Detalhes da ideia</h3><label class="field"><span>Anota&ccedil;&otilde;es de produ&ccedil;&atilde;o</span><textarea id="ideaDetailNotes" rows="8" placeholder="Registre decis&otilde;es, ajustes ou como pretende adaptar esta ideia."></textarea></label><p class="micro">As anota&ccedil;&otilde;es ficam salvas nesta ideia.</p></aside></div></div></dialog></section>',
    designBank:'<section class="panel"><p class="eyebrow">REPERT&Oacute;RIO VISUAL DA MARCA</p><h2>Banco de design</h2><p class="micro">Guarde refer&ecirc;ncias separadas por perfil e por formato. A Devil usa a leitura visual como dire&ccedil;&atilde;o, preservando identidade, textos e elementos pr&oacute;prios da marca.</p><div class="grid2"><label class="field">Perfil<select id="designBankProfile"></select></label><label class="field">Biblioteca<select id="designBankFormat"><option value="stories">Stories</option><option value="feed">Feed: carrossel e est&aacute;tico</option></select></label></div><label class="button">Adicionar inspira&ccedil;&otilde;es visuais<input id="designBankUpload" type="file" accept="image/*" multiple hidden></label><p class="micro" id="designBankStatus" role="status"></p><div id="designBankList" class="cards"></div></section>',
    portalAdmin:'<section class="panel portal-admin"><p class="eyebrow">PAINEL PRIVADO</p><h2>Administra&ccedil;&atilde;o de clientes</h2><p class="micro">Cadastre o perfil, o acesso e as listas da cliente. Os templates da equipe são compartilhados entre todos os perfis.</p><button type="button" class="button primary" id="portalAdminNewProfile">+ Cadastrar perfil da cliente</button><p class="micro">No cadastro, informe nome, @ do Instagram e anexe a bíblia de marca ou dossiê. Depois informe o e-mail e salve o acesso.</p><div class="grid2"><label class="field">Perfil da plataforma<select id="portalAdminProfile"></select></label><label class="field">E-mail de acesso da cliente<input id="portalAdminEmail" type="email" placeholder="cliente@exemplo.com"></label></div><div class="grid2"><label class="field">Nome exibido<input id="portalAdminName" placeholder="Nome do perfil"></label><label class="field">@ do Instagram<input id="portalAdminHandle" placeholder="@ da cliente" readonly></label></div><div class="grid2"><label class="field">Lista do ClickUp &middot; cronograma de publica&ccedil;&otilde;es<input id="portalClickUpSchedule" type="url" placeholder="Cole o link da lista de conte&uacute;do"></label><label class="field">Lista do ClickUp &middot; banco de ideias<input id="portalClickUpIdeas" type="url" placeholder="Cole o link do banco de ideias"></label></div><div class="action-row"><button class="button primary" id="portalAdminSave">Salvar acesso e listas</button><button class="button" id="portalAdminLoad">Carregar cliente</button><button class="button" id="portalAdminSyncNow">Sincronizar ClickUp agora</button><button class="button" id="portalAdminPublish">Publicar ideias e conte&uacute;dos</button><button class="button" id="portalAdminPreview">Visualizar como cliente</button></div><p class="micro">Para @divarebel.on, configure a lista Conte&uacute;do no campo do cronograma e BANCO DE IDEIAS &mdash; SOCIAL MEDIA no campo de ideias. Cada cliente usa listas pr&oacute;prias.</p><p id="portalAdminStatus" class="micro" role="status"></p><div id="portalAdminClients" class="cards"></div><div id="portalAdminPreviewBox"></div><section class="admin-repertoire"><p class="eyebrow">REPERTÓRIO PRIVADO · SÓ ADMIN</p><h2>Repertório de conteúdo</h2><p class="micro">Organize seu método por formato. Cada repertório é exclusivo da administradora.</p><div class="rep-format-tabs" role="tablist" aria-label="Formato do repertório"><button type="button" data-rep-format="stories" aria-pressed="true">Stories</button><button type="button" data-rep-format="reel" aria-pressed="false">Reels</button><button type="button" data-rep-format="carousel" aria-pressed="false">Carrossel</button><button type="button" data-rep-format="design" aria-pressed="false">Design</button></div><div class="rep-kind-tabs" role="tablist" aria-label="Categoria"><button type="button" data-rep-kind="studies" aria-pressed="true">Estudos e conhecimento</button><button type="button" data-rep-kind="sequences" aria-pressed="false">Sequências validadas</button></div><p class="micro" id="repKindDescription"></p><form id="repForm" class="rep-form"><div class="grid2"><label class="field">Nome do material<input id="repTitle" required maxlength="180" placeholder="Ex.: Narrativa premium de vendas"></label><label class="field">Link de referência (opcional)<input id="repUrl" type="url" placeholder="https://..."></label></div><label class="field">Contexto e conteúdo<textarea id="repText" rows="7" placeholder="Registre o estudo, conhecimento, estrutura ou sequência validada."></textarea></label><label class="field">Anexar material (opcional)<input id="repFiles" type="file" multiple accept=".pdf,.txt,.md,.docx,.doc,.jpg,.jpeg,.png,.webp,.mp4,.webm,.mov,.m4v,application/pdf,text/plain,image/*,video/*"></label><p class="micro">Os materiais e anexos ficam salvos na conta privada da administradora.</p><div class="action-row"><button type="submit" class="button primary" id="repSave">Adicionar ao repertório</button><span id="repStatus" class="micro" role="status"></span></div></form><div id="repItems" class="rep-items"></div></section></section>',    approvals:'<section class="panel"><p class="eyebrow">REVISÃO VISUAL · FLUXO INTERNO</p><h2>Conteúdos para aprovação</h2><p class="micro">Organize peças por cliente, navegue como um carrossel, amplie cada arte, registre comentários por slide e marque o que foi aprovado. Esta área permanece privada na sua conta.</p><div class="grid2"><label class="field">Cliente<select id="approvalProfile"></select></label><label class="field">Nome da publicação<input id="approvalTitle" placeholder="Ex.: Carrossel sobre consulta"></label></div><div class="grid2"><label class="field">Link do calendário do ClickUp<input id="approvalCalendarUrl" type="url" placeholder="Cole o link do calendário/lista"></label><label class="field">E-mail de acesso ao portal<input id="approvalClientEmail" type="email" placeholder="E-mail da cliente"></label></div><div class="action-row"><button class="button" id="approvalCalendarSave">Salvar calendário</button><button class="button primary" id="approvalCalendarSync">Sincronizar calendário</button><button class="button primary" id="addCurrentApproval">Adicionar o conteúdo aberto</button><label class="button">Enviar artes finais (uma imagem por slide)<input id="approvalFiles" type="file" accept="image/*" multiple hidden></label></div><p class="micro" id="approvalStatus" role="status"></p><div class="approval-mode-row"><div class="approval-mode-seg" id="approvalModeSeg" role="group" aria-label="Modo de visualiza&ccedil;&atilde;o"><button type="button" data-approval-mode="grid" class="active">▦ Grade</button><button type="button" data-approval-mode="feed">☰ Feed</button></div></div><div id="approvalList" class="cards"></div><dialog class="dialog approval-zoom" id="approvalZoom"><div class="dialog-head"><h2 id="approvalZoomTitle">Prévia</h2><button class="close" data-close="approvalZoom">×</button></div><div class="approval-zoom-controls"><button class="button tiny" id="approvalPrev">\u2190 Anterior</button><span id="approvalZoomPosition" class="micro"></span><button class="button tiny" id="approvalNext">Pr\u00f3ximo \u2192</button></div><div id="approvalZoomBody"></div><label class="field">Coment\u00e1rio deste slide<textarea id="approvalZoomComment" rows="3" placeholder="Escreva o ajuste ou observa\u00e7\u00e3o para este slide"></textarea></label><label class="approval-zoom-approved"><input id="approvalZoomCheck" type="checkbox"> Aprovado</label></dialog></section>'
  };
  Object.keys(views).forEach(k=>main.insertAdjacentHTML('beforeend','<section class="view" id="view-'+k+'">'+views[k]+'</section>'));
  if(!document.querySelector('#adminRepertoireStyle'))document.head.insertAdjacentHTML('beforeend','<style id="adminRepertoireStyle">.admin-repertoire{margin-top:28px;padding-top:22px;border-top:1px solid var(--line)}.rep-format-tabs,.rep-kind-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.rep-format-tabs button,.rep-kind-tabs button{border:1px solid var(--line);border-radius:999px;background:var(--panel2);color:var(--text);padding:9px 15px;cursor:pointer}.rep-format-tabs button[aria-pressed=true],.rep-kind-tabs button[aria-pressed=true]{background:var(--accent,#a78bfa);color:#19151f;border-color:transparent;font-weight:700}.rep-form{padding:16px;border:1px solid var(--line);border-radius:14px;background:var(--panel2)}.rep-items{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;margin-top:18px}.rep-item{padding:15px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.rep-item h3{margin:0 0 8px;overflow-wrap:anywhere}.rep-item-content{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.55;max-height:320px;overflow:auto;margin:10px 0}.rep-item-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.rep-item a{overflow-wrap:anywhere}.rep-empty{padding:18px;border:1px dashed var(--line);border-radius:12px;color:var(--muted)}@media(max-width:650px){.rep-form .grid2{grid-template-columns:1fr}}</style>');
  const repOwner=()=>String(api.user?.email||'').trim().toLowerCase()==='divarebel.on@gmail.com';
  const repNav=nav.querySelector('[data-view="portalAdmin"]');
  const syncRepAccess=()=>{if(repNav)repNav.hidden=!repOwner();if(!repOwner()&&api.app?.view==='portalAdmin')api.setView('studio')};
  syncRepAccess();window.addEventListener('devil:data-ready',syncRepAccess);
  let repFormat='stories',repKind='studies';
  const repDescriptions={studies:'Estudos, referências e conhecimentos sobre escrita, narrativa e criação para este formato.',sequences:'Sequências prontas que já foram testadas e validadas para reutilizar e adaptar.'};
  const repTitle=name=>({stories:'Stories',reel:'Reels',carousel:'Carrossel',design:'Design'}[name]||'Stories');
  async function renderRep(){
    const box=$('#repItems');if(!box)return;
    $('#repKindDescription').textContent=repDescriptions[repKind];
    document.querySelectorAll('[data-rep-format]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.repFormat===repFormat)));
    document.querySelectorAll('[data-rep-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.repKind===repKind)));
    const rows=(app().adminRepertoire||[]).filter(x=>x.format===repFormat&&x.kind===repKind).sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));
    if(!rows.length){box.innerHTML='<div class="rep-empty">Ainda não há materiais em '+esc(repTitle(repFormat))+' · '+esc(repKind==='studies'?'Estudos e conhecimento':'Sequências validadas')+'.</div>';return}
    box.innerHTML=rows.map(x=>'<article class="rep-item"><p class="eyebrow">'+esc(repTitle(x.format))+' · '+esc(x.kind==='studies'?'ESTUDO':'SEQUÊNCIA VALIDADA')+'</p><h3>'+esc(x.title)+'</h3>'+(x.url?'<p><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">Abrir referência ↗</a></p>':'')+(x.text?'<div class="rep-item-content">'+esc(x.text)+'</div>':'')+((x.files||[]).map(f=>'<p><a href="#" data-rep-file="'+esc(f.id)+'" data-rep-name="'+esc(f.name)+'">'+esc(f.name)+' ↗</a></p>').join(''))+'<div class="rep-item-actions"><button class="button tiny" type="button" data-rep-delete="'+esc(x.id)+'">Excluir</button></div></article>').join('');
  }
  document.querySelectorAll('[data-rep-format]').forEach(b=>b.addEventListener('click',()=>{repFormat=b.dataset.repFormat;renderRep()}));
  document.querySelectorAll('[data-rep-kind]').forEach(b=>b.addEventListener('click',()=>{repKind=b.dataset.repKind;renderRep()}));
