  function bubbleIdeaContext(idea,description,guidance){const card=bubble('','assistant');card.classList.add('idea-context-message');const title=document.createElement('strong');title.textContent='Contexto da ideia carregado';card.append(title);const meta=document.createElement('p');meta.textContent=idea.title||idea.author||'Ideia selecionada';card.append(meta);if(description){const details=document.createElement('details'),summary=document.createElement('summary'),body=document.createElement('p');summary.textContent='Ver descrição original completa';body.textContent=description;details.append(summary,body);card.append(details)}const fields=[['Objetivo',guidance?.objective],['Conexão com a audiência',guidance?.audienceFit],['Adaptação sugerida',guidance?.adaptation],['Execução',guidance?.execution],['Dicas de gravação/visual',guidance?.filming],['Adaptação para carrossel',guidance?.carousel],['CTA',guidance?.cta]].filter(x=>x[1]);if(fields.length){const list=document.createElement('ul');fields.forEach(([label,value])=>{const li=document.createElement('li');li.textContent=label+': '+value;list.append(li)});card.append(list)}const addLink=(url,label)=>{try{const parsed=new URL(url);if(parsed.protocol!=='https:')return;const a=document.createElement('a');a.href=parsed.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label+' ↗';card.append(a)}catch{}};const source=idea.sourceUrl||'',task=idea.clickupUrl||'';if(source&&source!==task)addLink(source,'Abrir inspiração');if(task)addLink(task,'Abrir tarefa no ClickUp');thread.scrollTop=thread.scrollHeight}
